/**
 * Shared store setup for workflow designers (v2 and advanced).
 *
 * Both designers initialize the same Pinia stores (WorkflowBuilderStore + DropdownStore)
 * with the same refs and methods. This composable centralizes that setup.
 *
 * Usage in Options API setup():
 *   const shared = useWorkflowStoreSetup();
 *   return { ...shared, ...otherSetupValues };
 */

import { ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useWorkflowBuilderStore, useDropdownStore } from 'src/store/main';

export interface WorkflowStoreSetupOptions {
  includeEmailTemplate?: boolean;
}

export function useWorkflowStoreSetup(options?: WorkflowStoreSetupOptions) {
  const workflow_builder_store = useWorkflowBuilderStore();
  workflow_builder_store.$reset();

  const {
    getWorkflowAllCards,
    setDocOperatorVariables,
    getCardsByType,
    getAllCards,
    getSearchResults,
  } = workflow_builder_store;

  const {
    workflowModel,
    workflowWhenCards,
    workflowAndCards,
    workflowThenCards,
    selectedAndCards,
    selectedWhenCards,
    selectedThenCards,
    cardToTest,
    docOperatorVariables,
    docOperatorVariablesSensitive,
    docOperatorLockedSensitiveData,
  } = storeToRefs(workflow_builder_store);

  const dropdown_store = useDropdownStore();
  const {
    prepareUsersDropdown,
    getSubOrgsList,
    prepareDocTypeAndSubTypesList,
    prepareTableNameDropdown,
    prepareAllDocumentTableColumnsDropdown,
    prepareGroupsDropdown,
    prepareWorkflowNameDropdown,
    prepareMasterDataTableDropdown,
    prepareExportConfigurationDropdown,
    prepareDecisionTableDropdown,
    prepareDocOperatorDropdown,
    preparePODisplayColsDropdown,
    prepareEmailTemplateDropdown,
  } = dropdown_store;

  const { doc_operator_prompts } = storeToRefs(dropdown_store);

  const result = {
    // Store refs
    workflowModel,
    workflowWhenCards,
    workflowAndCards,
    workflowThenCards,
    selectedAndCards,
    selectedWhenCards,
    selectedThenCards,
    cardToTest,
    docOperatorVariables,
    docOperatorVariablesSensitive,
    docOperatorLockedSensitiveData,
    // Store methods
    getWorkflowAllCards,
    setDocOperatorVariables,
    getCardsByType,
    getAllCards,
    getSearchResults,
    // Dropdown methods
    prepareUsersDropdown,
    getSubOrgsList,
    prepareDocTypeAndSubTypesList,
    prepareTableNameDropdown,
    prepareAllDocumentTableColumnsDropdown,
    prepareGroupsDropdown,
    prepareWorkflowNameDropdown,
    prepareMasterDataTableDropdown,
    prepareExportConfigurationDropdown,
    prepareDecisionTableDropdown,
    prepareDocOperatorDropdown,
    preparePODisplayColsDropdown,
    prepareEmailTemplateDropdown: options?.includeEmailTemplate ? prepareEmailTemplateDropdown : undefined,
    // Dropdown refs
    doc_operator_prompts,
    // Common UI state
    ShowTemplateDashboard: ref(false),
    ShowTestCardDialog: ref(false),
  };

  return result;
}
