<template>
  <q-dialog :model-value="modelValue" maximized @update:model-value="$emit('update:modelValue', $event)" @hide="$emit('hide')">
    <q-card :class="['cards-dialog', 'dialog-bg', { 'cards-dialog--dark': $q.dark.isActive }]">
      <q-toolbar class="dialog-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold text-capitalize">{{ $t(cardType) }}...</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="paddingMargin0">
        <div class="dialog-layout">
          <div class="categories-panel">
            <q-input
              :model-value="searchValue"
              :label="$t('wf_search_card')"
              @update:model-value="$emit('update:searchValue', $event)"
            >
              <template v-slot:append>
                <q-icon name="search" />
              </template>
            </q-input>

            <div class="row q-pb-sm q-pl-sm fontGrey">
              {{ $t('wf_categories') }}
            </div>

            <div
              v-for="(item, index) in category"
              :key="index"
              :class="activeSubCategory == item.category ? 'active-category-card' : 'category-card'"
              @click="$emit('select-category', item)"
            >
              <div class="row items-center">
                <div
                  class="category-squircle"
                  :style="categoryIconStyle(item.svg_background_color)"
                >
                  <i v-html="item.svg" class="svg-icon" />
                </div>
                <span class="category-text">{{ $t(item.category) }}</span>
                <q-icon name="arrow_forward_ios" size="20px" class="icon" />
              </div>
            </div>
          </div>

          <div class="cards-grid-area box-margin">
            <slot name="cards" :cards="filteredCards.cards" :svg="filteredCards.svg" />
          </div>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';

export default defineComponent({
  name: 'WorkflowCardPickerDialog',
  props: {
    modelValue: {
      type: Boolean,
      required: true,
    },
    cardType: {
      type: String,
      required: true,
    },
    category: {
      type: Array as PropType<any[]>,
      default: () => [],
    },
    filteredCards: {
      type: Object as PropType<{ cards: any[]; svg?: string }>,
      default: () => ({ cards: [], svg: '' }),
    },
    activeSubCategory: {
      type: String,
      default: '',
    },
    searchValue: {
      type: String,
      default: '',
    },
  },
  emits: ['update:modelValue', 'update:searchValue', 'select-category', 'hide'],
  methods: {
    categoryIconStyle(color: string): Record<string, string> {
      const rgb = this.parseHex(color);
      const darker = rgb
        ? `#${rgb.map((c) => Math.max(0, Math.round(c * 0.75)).toString(16).padStart(2, '0')).join('')}`
        : '#666666';
      return {
        background: `linear-gradient(135deg, ${color}, ${darker})`,
        boxShadow: `0 2px 8px ${this.hexToRgba(color, 0.25)}`,
      };
    },
    parseHex(hex: string): [number, number, number] | null {
      if (!hex || !hex.startsWith('#') || hex.length < 7) return null;
      return [
        parseInt(hex.slice(1, 3), 16),
        parseInt(hex.slice(3, 5), 16),
        parseInt(hex.slice(5, 7), 16),
      ];
    },
    hexToRgba(hex: string, alpha: number): string {
      const rgb = this.parseHex(hex);
      if (!rgb) return `rgba(150,150,150,${alpha})`;
      return `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`;
    },
  },
});
</script>

