/**
 * Shared dropdown initialization for workflow designers (v2 and advanced).
 *
 * Both designers load the same set of dropdown data in mounted().
 * This utility centralizes that into a single function.
 */

export interface DropdownContext {
  prepareUsersDropdown: () => Promise<void>;
  getSubOrgsList: () => Promise<void>;
  prepareDocTypeAndSubTypesList: () => Promise<void>;
  prepareTableNameDropdown: () => Promise<void>;
  prepareAllDocumentTableColumnsDropdown: () => Promise<void>;
  prepareGroupsDropdown: () => Promise<void>;
  prepareWorkflowNameDropdown: () => Promise<void>;
  prepareMasterDataTableDropdown: () => Promise<void>;
  prepareExportConfigurationDropdown: () => Promise<void>;
  prepareDecisionTableDropdown: () => Promise<void>;
  prepareDocOperatorDropdown: () => Promise<void>;
  preparePODisplayColsDropdown: () => Promise<void>;
  prepareEmailTemplateDropdown?: () => Promise<void>;
}

export async function initChildDropdowns(ctx: DropdownContext): Promise<void> {
  const promises: Promise<void>[] = [
    ctx.prepareUsersDropdown(),
    ctx.getSubOrgsList(),
    ctx.prepareDocTypeAndSubTypesList(),
    ctx.prepareTableNameDropdown(),
    ctx.prepareAllDocumentTableColumnsDropdown(),
    ctx.prepareGroupsDropdown(),
    ctx.prepareWorkflowNameDropdown(),
    ctx.prepareMasterDataTableDropdown(),
    ctx.prepareExportConfigurationDropdown(),
    ctx.prepareDecisionTableDropdown(),
    ctx.prepareDocOperatorDropdown(),
    ctx.preparePODisplayColsDropdown(),
  ];
  if (ctx.prepareEmailTemplateDropdown) {
    promises.push(ctx.prepareEmailTemplateDropdown());
  }
  await Promise.allSettled(promises);
}
